            JavaScript

    function reverseInGroups(arr, k) {

    let n = arr.length; 

    for (let i = 0; i < n; i += k) {
        let left = i;

        // to handle case when k is not multiple of n
        let right = Math.min(i + k - 1, n - 1);

        // reverse the sub-array [left, right]
        while (left < right) {

            // Swap elements
            [arr[left], arr[right]] = [arr[right], arr[left]];
            left += 1;
            right -= 1;
        }
    }
    return arr;
}

